import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CHX4lV2z.js";const k=JSON.parse('{"title":"DeepSeek Harness","description":"","frontmatter":{},"headers":[],"relativePath":"hosts/deepseek-harness.md","filePath":"hosts/deepseek-harness.md","lastUpdated":1789811186000}'),n={name:"hosts/deepseek-harness.md"};function o(l,e,d,r,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="deepseek-harness" tabindex="-1">DeepSeek Harness <a class="header-anchor" href="#deepseek-harness" aria-label="Permalink to &quot;DeepSeek Harness&quot;">​</a></h1><p>TokenPilot integrates with DeepSeek Harness as a native <strong>Cordis plugin</strong>, registered as <code>tokenpilot-dsh</code>. It uses task-state estimation to identify completed work and can replace eligible older content in the context that Harness sends to the model.</p><p>Harness continues to own model transport, session persistence, and native compaction. The adapter adds optional context eviction and a read-only session status command; it does not add the proxy-based stable-prefix and reduction pipeline used by other hosts.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Use Node.js <strong>22.19 or later in the 22.x line, or 24 and later</strong>, as required by the adapter package. You need a LightRSI checkout with workspace dependencies installed and a working DeepSeek Harness checkout.</p><p>From the LightRSI repository root, build and package the adapter:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @lightrsi/deepseek-harness-adapter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @lightrsi/deepseek-harness-adapter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack-destination</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./artifacts</span></span></code></pre></div><p>From your DeepSeek Harness checkout, add the generated archive to the profile you use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx/esm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/cli/src/bin.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/lightrsi-deepseek-harness-adapter-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tgz</span></span></code></pre></div><p>Replace the archive path with the actual file produced by the pack command. Replace <code>web</code> with your chosen profile, such as <code>headless</code>.</p><p>The package registers the Cordis plugin, but <strong>eviction is disabled by default</strong>. Installing it alone does not enable context changes.</p><h2 id="configure-and-enable" tabindex="-1">Configure and Enable <a class="header-anchor" href="#configure-and-enable" aria-label="Permalink to &quot;Configure and Enable&quot;">​</a></h2><p>Edit the installed profile&#39;s <code>cordis.patch.yml</code>. For the default Harness home and the <code>web</code> profile, this is <code>~/.dsh/profiles/web/cordis.patch.yml</code>; with a custom home, use <code>$DSH_HOME/profiles/web/cordis.patch.yml</code>. Replace <code>web</code> if you installed into another profile. See the upstream <a href="https://github.com/deepseek-ai/deepseek-harness/blob/dd6322d604e00eec1ba5e0c8541159906a21094a/packages/boot/app-boot/README.md#profiles" target="_blank" rel="noreferrer">profile configuration documentation</a> and <a href="https://github.com/deepseek-ai/deepseek-harness/blob/dd6322d604e00eec1ba5e0c8541159906a21094a/packages/util/home-paths/README.md" target="_blank" rel="noreferrer">Harness home resolution</a>.</p><p>Add this entry to the existing patch list, or update its existing <code>tokenpilot-dsh</code> entry:</p><p>The package installation has already inserted the plugin entry. This profile patch updates it by <code>id</code>; it does not insert another entry, and <code>name</code> does not need to be repeated. These rules follow the pinned Harness <a href="https://github.com/deepseek-ai/deepseek-harness/blob/dd6322d604e00eec1ba5e0c8541159906a21094a/vendor/include/src/index.ts" target="_blank" rel="noreferrer">patch implementation</a>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tokenpilot-dsh</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    stateDir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/absolute/path/to/tokenpilot-dsh-state</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    taskStateEstimator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      baseUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://your-estimator-endpoint/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      apiKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_ESTIMATOR_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-estimator-model</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    eviction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    compaction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      runEvictionBeforeCompaction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Replace the placeholders with your own settings. Keep credentials in local configuration, outside version control. <code>stateDir</code> must point to a writable, persistent directory: it stores task lifecycle state across restarts.</p><p>A patch replaces the matched plugin&#39;s entire configuration, so retain any other TokenPilot settings you already use. Home-level patches and explicit overlays can override profile settings.</p><p>The shipped <code>web</code> profile uses <code>patchReload: live</code>, so a valid patch edit is applied without restarting. Profiles configured with <code>patchReload: startup</code> (including the shipped <code>headless</code>, <code>sdk</code>, <code>sdk-minimal</code>, and <code>acp</code> templates) require a restart with the same profile.</p><p>Eviction requires the master switch, estimator switch, and eviction switch to be enabled, a configured estimator endpoint, API key and model, and a durable state directory. If those requirements are not met, the adapter skips context changes and lets the agent continue.</p><h3 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Default</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>enabled</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Enable the adapter&#39;s eviction handler</td></tr><tr><td style="text-align:left;"><code>stateDir</code></td><td style="text-align:left;">Unset</td><td style="text-align:left;">Persistent directory for the task registry</td></tr><tr><td style="text-align:left;"><code>taskStateEstimator.enabled</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Enable task-state estimation</td></tr><tr><td style="text-align:left;"><code>taskStateEstimator.baseUrl</code>, <code>apiKey</code>, <code>model</code></td><td style="text-align:left;">Unset</td><td style="text-align:left;">Endpoint, credentials, and model for the estimator</td></tr><tr><td style="text-align:left;"><code>taskStateEstimator.requestTimeoutMs</code></td><td style="text-align:left;"><code>60000</code></td><td style="text-align:left;">Estimator request timeout in milliseconds</td></tr><tr><td style="text-align:left;"><code>taskStateEstimator.batchTurns</code></td><td style="text-align:left;"><code>5</code></td><td style="text-align:left;">Turn batch size passed to the estimator</td></tr><tr><td style="text-align:left;"><code>taskStateEstimator.evictionLookaheadTurns</code></td><td style="text-align:left;"><code>3</code></td><td style="text-align:left;">Lookahead window passed to the estimator</td></tr><tr><td style="text-align:left;"><code>eviction.enabled</code></td><td style="text-align:left;"><code>false</code></td><td style="text-align:left;">Allow eligible context to be replaced</td></tr><tr><td style="text-align:left;"><code>eviction.minBlockChars</code></td><td style="text-align:left;"><code>200</code></td><td style="text-align:left;">Minimum candidate block size in characters</td></tr><tr><td style="text-align:left;"><code>eviction.failureMode</code></td><td style="text-align:left;"><code>bypass</code></td><td style="text-align:left;">Continue the agent when optimization fails</td></tr><tr><td style="text-align:left;"><code>compaction.runEvictionBeforeCompaction</code></td><td style="text-align:left;"><code>true</code></td><td style="text-align:left;">Run TokenPilot before Harness native compaction</td></tr><tr><td style="text-align:left;"><code>logLevel</code></td><td style="text-align:left;"><code>info</code></td><td style="text-align:left;">Set to <code>debug</code> to inspect pre-step decisions</td></tr></tbody></table><h2 id="verify-in-a-session" tabindex="-1">Verify in a Session <a class="header-anchor" href="#verify-in-a-session" aria-label="Permalink to &quot;Verify in a Session&quot;">​</a></h2><p>After loading the configured profile, open a Harness session and run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/tokenpilot-status</span></span></code></pre></div><p>This command reads session state without creating a model turn or modifying context. It reports:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>enabled</code></td><td style="text-align:left;">Whether the adapter&#39;s master switch is enabled</td></tr><tr><td style="text-align:left;"><code>last estimator run</code></td><td style="text-align:left;">The most recent recorded estimator run</td></tr><tr><td style="text-align:left;"><code>candidate count</code></td><td style="text-align:left;">Recorded candidate count, or <code>unknown</code> when unavailable</td></tr><tr><td style="text-align:left;"><code>estimated</code></td><td style="text-align:left;">Estimated token savings</td></tr><tr><td style="text-align:left;"><code>scheduled</code></td><td style="text-align:left;">Work that reached the candidate or transaction stage</td></tr><tr><td style="text-align:left;"><code>applied</code></td><td style="text-align:left;">Token savings supported by recorded application evidence</td></tr><tr><td style="text-align:left;"><code>deferred reasons</code></td><td style="text-align:left;">Reasons work could not be applied</td></tr><tr><td style="text-align:left;"><code>last transaction status</code></td><td style="text-align:left;">The latest recorded eviction transaction outcome</td></tr></tbody></table><p>An enabled adapter does not guarantee an eviction on every turn. A new session may report <code>never</code>, <code>none</code>, or <code>unknown</code> until relevant events have been recorded. Estimated and scheduled savings are not proof that a context change was applied.</p><p>The status command requires Harness&#39;s <code>commands</code> and <code>sessionProjections</code> services. A headless composition without those services can load the adapter but will not expose this command.</p><h2 id="how-eviction-works" tabindex="-1">How Eviction Works <a class="header-anchor" href="#how-eviction-works" aria-label="Permalink to &quot;How Eviction Works&quot;">​</a></h2><p>On an eligible agent step, TokenPilot reads session events, updates task lifecycle state, validates eviction candidates, and applies replacements to the current context. By default, this runs <strong>before Harness native compaction</strong>, then re-measures context size so subsequent processing sees the updated size.</p><p>The safety checks retain current-turn content, active or unresolved tasks, and compaction checkpoints. Tool results are eligible only when their call/result relationship is complete and safe; the assistant&#39;s tool-call structure is preserved. A changed session revision or unsupported required event prevents an unsafe rewrite.</p><p>Optimization failures use the <code>bypass</code> policy so the agent can continue. Preserve the default compaction ordering unless you are deliberately testing a different configuration.</p><p>Replacements are recorded as new session events; the original event log remains available for audit and replay. If only part of a replacement batch succeeds, the adapter records a partial result rather than claiming that all changes were rolled back.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Symptom</th><th style="text-align:left;">What to check</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/tokenpilot-status</code> is unavailable</td><td style="text-align:left;">Confirm the plugin was added to the active profile and that the profile supplies both command and session projection services</td></tr><tr><td style="text-align:left;">Status shows <code>enabled: no</code></td><td style="text-align:left;">Enable the <code>tokenpilot-dsh</code> master switch in that profile</td></tr><tr><td style="text-align:left;">No estimator activity or eviction</td><td style="text-align:left;">Check the estimator and eviction switches, estimator endpoint/key/model, and persistent <code>stateDir</code></td></tr><tr><td style="text-align:left;">Tasks remain in context</td><td style="text-align:left;">They may still be active, unresolved, current, too small, or fail tool-pair safety checks; inspect deferrals before expecting savings</td></tr><tr><td style="text-align:left;">Optimization is skipped</td><td style="text-align:left;">Set <code>logLevel</code> to <code>debug</code> and inspect <code>[tokenpilot:dsh] pre-step</code> logs for reasons such as <code>estimator-not-configured</code>, <code>registry-not-configured</code>, or <code>unrecognized-required-event</code></td></tr></tbody></table><p>To disable automatic eviction, set <code>eviction.enabled</code> to <code>false</code>. To disable the eviction handler entirely, set the top-level <code>enabled</code> to <code>false</code>, then reload the configured profile. Disabling future eviction does not undo context changes already applied.</p><h2 id="integration-boundaries" tabindex="-1">Integration Boundaries <a class="header-anchor" href="#integration-boundaries" aria-label="Permalink to &quot;Integration Boundaries&quot;">​</a></h2><p>DeepSeek Harness uses its own plugin installation and <code>/tokenpilot-status</code> command. The shared <code>lightrsi ... doctor</code>, <code>report</code>, <code>visual</code>, and runtime-mode walkthroughs for other hosts do not apply to this integration.</p><p>The current Cordis entrypoint does not expose a public <a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> workflow. Cleaner backend modules in the repository do not make <code>/tokenpilot-status</code> an interactive clean command; automatic eviction and user-approved Cleaner plans are separate capabilities.</p><p>For adapter development, see <a href="/LightRSI/host-adapter-development/adapter-testing">Adapter Testing</a>. The compatibility smoke checks package installation and host integration; it is separate from validating eviction with your estimator and live sessions.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>The install and session commands follow the project <a href="https://github.com/zjunlp/LightRSI/blob/main/README.md#installation" target="_blank" rel="noreferrer">README</a>. The additional configuration defaults and status fields are defined by the adapter&#39;s <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/deepseek-harness/src/config.ts" target="_blank" rel="noreferrer">configuration</a> and <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/deepseek-harness/src/commands.ts" target="_blank" rel="noreferrer">status command</a>.</p><ul><li><a href="/LightRSI/hosts/compatibility">Host Compatibility</a> — compare integration capabilities</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot Overview</a> — understand the context-management techniques</li></ul>`,44)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
